select distinct(pokemon_species.identifier) from pokemon_species join pokemon_egg_groups on pokemon_species.id = pokemon_egg_groups.species_id
join egg_groups on pokemon_egg_groups.egg_group_id = egg_groups.id join pokemon_habitats on pokemon_species.habitat_id = pokemon_habitats.id
where egg_groups.identifier = 'humanshape' or pokemon_habitats.identifier = 'urban' order by pokemon_species.identifier;